148		CS(false);
149		uint8_t cmd[4] = {
150			0x03,
151			(uint8_t) (address >> 16) & 0xFF,
152			(uint8_t) (address >> 8) & 0xFF,
153			(uint8_t) (address & 0xFF),
154		};
155		// issue read command
156		HAL_SPI_Transmit(spi, cmd, 4, 100);
157	}
158	
159	bool Flash::WaitBusy(uint32_t timeout) {
160		uint32_t starttime = HAL_GetTick();
161		CS(false);
162		uint8_t readStatus1 = 0x05;
163		HAL_SPI_Transmit(spi, &readStatus1, 1, 100);
164		do {
165			vTaskDelay(1);
166			uint8_t status1;
167			HAL_SPI_Receive(spi, &status1, 1, 100);
168			if (!(status1 & 0x01)) {
169				CS(true);
170				return true;
171			}
172		} while (HAL_GetTick() - starttime < timeout);
173		// timed out
174		CS(true);
175		LOG_ERR("Timeout occured");
176		return false;
177	}
178	
179	bool Flash::eraseRange(uint32_t start, uint32_t len) {
180		if(start % SectorSize != 0) {
181			LOG_ERR("Start address of range has to be sector aligned (is %lu)", start);
182			return false;
183		}
184		if(len % SectorSize != 0) {
185			LOG_ERR("Length of range has to be multiple of sector size (is %lu)", len);
186			return false;
187		}
188		uint32_t erased_len = 0;
189		while(erased_len < len) {
190			uint32_t remaining = len - erased_len;
191			if(remaining >= Block64Size && start % Block64Size == 0) {
192				erase64Block(start);
193				erased_len += Block64Size;
194				start += Block64Size;
195				continue;
196			}
197			if(remaining >= Block32Size && start % Block32Size == 0) {
198				erase32Block(start);
199				erased_len += Block32Size;
200				start += Block32Size;
201				continue;
202			}
203			if(remaining >= SectorSize && start % SectorSize == 0) {
204				eraseSector(start);
205				erased_len += SectorSize;
206				start += SectorSize;
207				continue;
208			}
209			// Should never get here
210		}
211		return true;
212	}
