166	void AmplitudeCalDialog::setAmplitude(double amplitude, unsigned int point, bool port2)
167	{
168	    if(point >= points.size()) {
169	        return;
170	    }
171	    if(port2) {
172	        points[point].amplitudePort2 = amplitude;
173	        points[point].port2set = true;
174	    } else {
175	        points[point].amplitudePort1 = amplitude;
176	        points[point].port1set = true;
177	    }
178	    edited = true;
179	    AmplitudeChanged(points[point], port2);
180	    if(mode == CalibrationMode::OnlyPort1 && !port2) {
181	        // apply result from port 1 to port 2 as well
182	        points[point].correctionPort2 = points[point].correctionPort1;
183	        points[point].port2set = points[point].port1set;
184	        points[point].amplitudePort2 = points[point].amplitudePort1;
185	    } else if(mode == CalibrationMode::OnlyPort2 && port2) {
186	        // apply result from port 2 to port 1 as well
187	        points[point].correctionPort1 = points[point].correctionPort2;
188	        points[point].port1set = points[point].port2set;
189	        points[point].amplitudePort1 = points[point].amplitudePort2;
190	    }
191	    model.dataChanged(model.index(point, model.ColIndexCorrectionFactors), model.index(point, model.ColIndexPort2));
192	    UpdateSaveButton();
193	}
