195	void AmplitudeCalDialog::ReceivedPoint(Protocol::AmplitudeCorrectionPoint p)
196	{
197	    qDebug() << "Received amplitude calibration point" << p.pointNum << "/" << p.totalPoints;
198	    CorrectionPoint c;
199	    c.frequency = p.freq * 10.0;
200	    c.correctionPort1 = p.port1;
201	    c.correctionPort2 = p.port2;
202	    c.port1set = false;
203	    c.port2set = false;
204	    model.beginInsertRows(QModelIndex(), points.size(), points.size());
205	    UpdateAmplitude(c);
206	    points.push_back(c);
207	    model.endInsertRows();
208	    emit pointsUpdated();
209	    if(p.pointNum == p.totalPoints - 1) {
210	        // this was the last point
211	        disconnect(this, &AmplitudeCalDialog::AmplitudeCorrectionPointReceived, this, nullptr);
212	        ui->load->setEnabled(true);
213	    }
214	}
