265	bool AmplitudeCalDialog::AddPoint(AmplitudeCalDialog::CorrectionPoint &p)
266	{
267	    if (points.size() >= dev->getMaxAmplitudePoints()) {
268	        // already at limit
269	        return false;
270	    }
271	    // find position at which this frequency gets inserted
272	    auto index = upper_bound(points.begin(), points.end(), p.frequency, [](double value, const CorrectionPoint& p){
273	        return value < p.frequency;
274	    });
275	    model.beginInsertRows(QModelIndex(), index - points.begin(), index - points.begin());
276	    emit newPointCreated(p);
277	    points.insert(index, p);
278	    model.endInsertRows();
279	    UpdateSaveButton();
280	    return true;
281	}
