360	void AmplitudeCalDialog::AutomaticMeasurementDialog()
361	{
362	    automatic = {};
363	    automatic.isSourceCal = pointType() == Protocol::PacketType::SourceCalPoint;
364	    const QString ownCal = automatic.isSourceCal ? "Source" : "Receiver";
365	    const QString otherCal = automatic.isSourceCal ? "Receiver" : "Source";
366	
367	    // compile info text
368	    QString info = "It is possible to determine the " + ownCal + " Calibration if a valid " + otherCal
369	            + " Calibration is already present. To do so, connect a short cable with as little loss as possible"
370	            + " between the ports. For each point in the " + otherCal + " Calibration, the device will take"
371	            + " a measurement and determine the correction factors for the " + ownCal + " Calibration.";
372	
373	    automatic.dialog = new QDialog(this);
374	    auto ui = new Ui::AutomaticAmplitudeDialog();
375	    ui->setupUi(automatic.dialog);
376	    connect(automatic.dialog, &QDialog::finished, [=](){
377	        delete ui;
378	    });
379	    automatic.progress = ui->progress;
380	    ui->explanation->setText(info);
381	    ui->status->setText("Gathering information about "+otherCal+" Calibration...");
382	
383	    automatic.points.clear();
384	
385	    connect(automatic.dialog, &QDialog::rejected, ui->abort, &QPushButton::click);
386	    connect(ui->abort, &QPushButton::clicked, [=](){
387	        // aborted, clean up
388	        disconnect(this, &AmplitudeCalDialog::SpectrumResultReceived, this, &AmplitudeCalDialog::ReceivedAutomaticMeasurementResult);
389	        dev->setIdle();
390	        delete ui;
391	        delete automatic.dialog;
392	    });
393	
394	    dev->setIdle();
395	    connect(this, &AmplitudeCalDialog::AmplitudeCorrectionPointReceived, this, [this, ui, otherCal](Protocol::AmplitudeCorrectionPoint p) {
396	        CorrectionPoint c;
397	        c.frequency = p.freq * 10.0;
398	        c.correctionPort1 = p.port1;
399	        c.correctionPort2 = p.port2;
400	        c.port1set = true;
401	        c.port2set = true;
402	        automatic.points.push_back(c);
403	        ui->progress->setValue(100 * (p.pointNum+1) / p.totalPoints);
404	        if(p.pointNum == p.totalPoints - 1) {
405	            // this was the last point, indicate ready for measurement
406	            ui->progress->setValue(0);
407	            ui->status->setText(otherCal + " Calibration contains " +QString::number(p.totalPoints)+" points, ready to start measurement");
408	            ui->start->setEnabled(true);
409	            disconnect(this, &AmplitudeCalDialog::AmplitudeCorrectionPointReceived, this, nullptr);
410	            qDebug() << "Received" << p.totalPoints << "points for automatic calibration";
411	        }
412	    }, Qt::QueuedConnection);
413	    // request points of otherCal
414	    // switch between source/receiver calibration
415	    auto request = automatic.isSourceCal ? Protocol::PacketType::RequestReceiverCal : Protocol::PacketType::RequestSourceCal;
416	    dev->sendWithoutPayload(request);
417	
418	    connect(ui->start, &QPushButton::clicked, [=](){
419	        // remove any exising points in own calibration and copy points from other calibration
420	        RemoveAllPoints();
421	        for(auto p : automatic.points) {
422	            AddPoint(p.frequency);
423	        }
424	        // intialize measurement state machine
425	        connect(this, &AmplitudeCalDialog::SpectrumResultReceived, this, &AmplitudeCalDialog::ReceivedAutomaticMeasurementResult, Qt::QueuedConnection);
426	        automatic.measuringPort2 = false;
427	        automatic.measuringCount = 0;
428	        ui->status->setText("Taking measurements...");
429	        SetupNextAutomaticPoint(automatic.isSourceCal);
430	    });
431	
432	    if(AppWindow::showGUI()) {
433	        automatic.dialog->show();
434	    }
435	}
