437	void AmplitudeCalDialog::ReceivedMeasurement(Protocol::SpectrumAnalyzerResult res)
438	{
439	    MeasurementResult m = {.port1 = Util::SparamTodB(res.port1), .port2 = Util::SparamTodB(res.port2)};
440	    sweepMeasurements.push_back(m);
441	    if(res.pointNum == automaticSweepPoints - 1) {
442	        // sweep finished, find maximum for each port
443	        double maxPort1 = std::numeric_limits<double>::lowest();
444	        double maxPort2 = std::numeric_limits<double>::lowest();
445	        for(auto s : sweepMeasurements) {
446	            if(s.port1 > maxPort1) {
447	                maxPort1 = s.port1;
448	            }
449	            if(s.port2 > maxPort2) {
450	                maxPort2 = s.port2;
451	            }
452	        }
453	        MeasurementResult max = {.port1 = maxPort1, .port2 = maxPort2};
454	        if(measured.size() >= averages) {
455	            measured.pop_front();
456	        }
457	        measured.push_back(max);
458	        sweepMeasurements.clear();
459	    }
460	}
