493	void AmplitudeCalDialog::SetupNextAutomaticPoint(bool isSourceCal)
494	{
495	    qDebug() << "Starting automatic calibration measurement for point" << automatic.measuringCount <<", measuring port2:" << automatic.measuringPort2;
496	    auto point = automatic.points[automatic.measuringCount];
497	    Protocol::PacketInfo p = {};
498	    p.type = Protocol::PacketType::SpectrumAnalyzerSettings;
499	    p.spectrumSettings.RBW = 10000;
500	    p.spectrumSettings.UseDFT = 0;
501	    // setup points centered around the measurement frequency:
502	    // use a span proportional to the center frequency (this makes sure to catch the peak of the excitation signal which
503	    // might be slightly off due to PLL divider limtis). Also make sure to use at least a span of 2 Hz (zero span not supported yet)
504	    p.spectrumSettings.f_stop = point.frequency * 1.00001 + 1.0;
505	    p.spectrumSettings.f_start = point.frequency / 1.00001 - 1.0;
506	    p.spectrumSettings.pointNum = automaticSweepPoints;
507	    p.spectrumSettings.Detector = 0;
508	    p.spectrumSettings.SignalID = 1;
509	    p.spectrumSettings.WindowType = 3;
510	    p.spectrumSettings.trackingGenerator = 1;
511	    p.spectrumSettings.trackingPower = excitationAmplitude * 100.0;
512	    p.spectrumSettings.trackingGeneratorOffset = 0;
513	    // For a source cal, the tracking generator has to be enabled at the measurement port (calibrating the output power)
514	    // For a receiver cal, the tracking generator has to be enabled at the other port (calibrating received power)
515	    if(isSourceCal) {
516	        if(automatic.measuringPort2) {
517	            p.spectrumSettings.trackingGeneratorPort = 1;
518	        } else {
519	            p.spectrumSettings.trackingGeneratorPort = 0;
520	        }
521	    } else {
522	        if(automatic.measuringPort2) {
523	            p.spectrumSettings.trackingGeneratorPort = 0;
524	        } else {
525	            p.spectrumSettings.trackingGeneratorPort = 1;
526	        }
527	    }
528	    if(isSourceCal) {
529	        // Calibrating the source which means the receiver is already calibrated -> use receiver corrections but no source corrections
530	        p.spectrumSettings.applyReceiverCorrection = 1;
531	        p.spectrumSettings.applySourceCorrection = 0;
532	    } else {
533	        // the other way around
534	        p.spectrumSettings.applyReceiverCorrection = 0;
535	        p.spectrumSettings.applySourceCorrection = 1;
536	    }
537	    automatic.settlingCount = averages + automaticSettling;
538	    dev->SendPacket(p);
539	    sweepMeasurements.clear();
540	    sweepMeasurements.reserve(automaticSweepPoints);
541	}
542	
543	void AmplitudeCalDialog::ReceivedAutomaticMeasurementResult(Protocol::SpectrumAnalyzerResult res)
544	{
545	    if(res.pointNum != automaticSweepPoints - 1) {
546	        // ignore everything except end of sweep
547	        return;
548	    }
549	    if(automatic.settlingCount > 0) {
550	        automatic.settlingCount--;
551	        return;
552	    }
553	    if(automatic.isSourceCal) {
554	        // grab correct measurement and convert to dbm
555	        auto m = averageMeasurement();
556	        double measurement = automatic.measuringPort2 ? m.port1 : m.port2;
557	        // receiver cal already done, the measurement result is accurate and can be used to determine actual output power
558	        setAmplitude(measurement, automatic.measuringCount, automatic.measuringPort2);
559	    } else {
560	        // source cal already done, the output power is accurate while the measurement might be off.
561	        // The measurement result is already extracted by the ReceiverCalDialog
562	        setAmplitude(excitationAmplitude, automatic.measuringCount, automatic.measuringPort2);
563	    }
564	    // update progress bar
565	    automatic.progress->setValue(100 * (automatic.measuringCount * 2 + automatic.measuringPort2 + 1) / (points.size() * 2));
566	    // advance state machine
567	    // switch ports
568	    automatic.measuringPort2 = !automatic.measuringPort2;
569	    if(!automatic.measuringPort2) {
570	        // now measuring port1, this means we have to advance to the next point
571	        automatic.measuringCount++;
572	        if(automatic.measuringCount >= points.size()) {
573	            // all done, close dialog
574	            // Closing the dialog will disconnect the connection to this function and return the device into the idle state
575	            automatic.dialog->reject();
576	            automatic.dialog = nullptr;
577	            qDebug() << "Automatic source/receiver calibration complete";
578	            return;
579	        }
580	    }
581	    // Start next measurement
582	    SetupNextAutomaticPoint(automatic.isSourceCal);
583	}
