585	AmplitudeCalDialog::MeasurementResult AmplitudeCalDialog::averageMeasurement()
586	{
587	    MeasurementResult ret = {};
588	    for(auto m : measured) {
589	        ret.port1 += m.port1;
590	        ret.port2 += m.port2;
591	    }
592	    ret.port1 /= measured.size();
593	    ret.port2 /= measured.size();
594	    return ret;
595	}
